-- =====================================================================
-- Deeper default clarification criteria: concrete hints (fields, report columns, rules, exceptions) and two new ones —
-- "typical case, step by step" (required) and "business rules". Document types whose criteria were never customised
-- (still exactly the old default) get the new list; customised ones are left alone.
-- =====================================================================
SET NAMES utf8mb4;

UPDATE document_types SET clarify_criteria = CAST('[{"key":"users","label":"Users","hint":"Each kind of user (role / department), roughly how many of each, and what each one does in the system","required":true},{"key":"current_process","label":"Current process & problem","hint":"How the work is done today step by step (paper, Excel, e-mail…), who does it, how long it takes, and exactly where it goes wrong — with a recent real example","required":true},{"key":"features","label":"Main features & scope","hint":"The functions the system must have, each as \\"who can do what\\" (e.g. \\"line leader submits a request\\"), and what is out of scope for now","required":true},{"key":"main_flow","label":"Typical case, step by step","hint":"Walk through one real case from start to finish: who does what, in what order, what each step needs and what it produces, and what happens when something is rejected or wrong","required":true},{"key":"key_user","label":"Key user","hint":"Who on the requestor side gives the details and tests / accepts the system (UAT)","required":true},{"key":"success","label":"Success criteria","hint":"How the requestor will know the project succeeded — a number or a before / after (e.g. \\"approval in 1 day instead of 3\\")","required":true},{"key":"data_io","label":"Data in & reports out","hint":"The fields to be entered (name, type, required or not, choices) and each report / document that must come out with its columns, filters and who reads it","required":false},{"key":"business_rules","label":"Business rules","hint":"Conditions, calculations, limits, statuses and validations (e.g. \\"over 50,000 THB needs manager approval\\", \\"stock cannot go below zero\\")","required":false},{"key":"integrations","label":"Other systems","hint":"Systems or files it must connect to (ERP, Excel, machines, e-mail…): which data, which direction, how often","required":false},{"key":"devices","label":"Devices & place of use","hint":"PC, mobile, tablet, shop floor — and whether it must work offline or with a scanner / printer","required":false},{"key":"approval_flow","label":"Approval steps","hint":"Who fills in, who approves, how many steps, what happens on reject, and who stands in when the approver is away","required":false},{"key":"permissions","label":"Permissions","hint":"Who may see, add, change or delete what — and anything that must be hidden from some people","required":false},{"key":"existing_data","label":"Existing data & volume","hint":"Old data to move in (where it is now, how clean), and how many records per day / month","required":false},{"key":"constraints","label":"Rules & constraints","hint":"Audit / standards (IATF, ISO), personal data (PDPA), and why the required date matters","required":false}]' AS JSON)
 WHERE clarify_criteria = CAST('[{"key":"users","label":"Users","hint":"Who will use the system, which departments, roughly how many people","required":true},{"key":"current_process","label":"Current process & problem","hint":"How the work is done today and what exactly goes wrong","required":true},{"key":"features","label":"Main features & scope","hint":"The main features / screens it must have, and what is out of scope","required":true},{"key":"key_user","label":"Key user","hint":"Who on the requestor side gives the details and tests / accepts the system (UAT)","required":true},{"key":"success","label":"Success criteria","hint":"How the requestor will know the project succeeded (measurable if possible)","required":true},{"key":"data_io","label":"Data in & reports out","hint":"What data is entered and which reports / documents must come out","required":false},{"key":"integrations","label":"Other systems","hint":"Systems or files it must connect to: ERP, Excel, machines, e-mail…","required":false},{"key":"devices","label":"Devices & place of use","hint":"PC, mobile, tablet, shop floor","required":false},{"key":"approval_flow","label":"Approval steps","hint":"Who fills in, who approves, how many steps","required":false},{"key":"permissions","label":"Permissions","hint":"Who may see or change what","required":false},{"key":"existing_data","label":"Existing data & volume","hint":"Old data to move in, and how much data per day / month","required":false},{"key":"constraints","label":"Rules & constraints","hint":"Audit / standards (IATF, ISO), personal data (PDPA), why the required date","required":false}]' AS JSON);
